#!/usr/bin/env bash
# Approve only the exact manifest commit generated by this successful build.
set -euo pipefail
: "${PR_NUMBER:?PR_NUMBER is required}"
: "${GITHUB_TOKEN:?GITHUB_TOKEN is required}"
: "${GITHUB_REPOSITORY:?GITHUB_REPOSITORY is required}"
: "${EXPECTED_HEAD_SHA:?EXPECTED_HEAD_SHA is required}"

if [[ -z "${REVIEW_TOKEN:-}" ]]; then
  echo '::warning::PENNYPILOT_REVIEW_TOKEN is not configured. A different identity must review a github-actions[bot] PR; leaving it for manual review.'
  if [[ -n "${GITHUB_STEP_SUMMARY:-}" ]]; then
    printf '\n**Approval pending:** configure `PENNYPILOT_REVIEW_TOKEN` from a separate identity, or review this PR manually.\n' >> "$GITHUB_STEP_SUMMARY"
  fi
  exit 0
fi
api="${GITHUB_API_URL:-https://api.github.com}/repos/${GITHUB_REPOSITORY}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
read_headers=(-H "Authorization: Bearer $GITHUB_TOKEN" -H 'Accept: application/vnd.github+json')
curl -fsS "${read_headers[@]}" "$api/pulls/$PR_NUMBER" > "$tmp/pr.json"
jq -e --arg sha "$EXPECTED_HEAD_SHA" --arg repo "$GITHUB_REPOSITORY" \
  '.state == "open" and .head.sha == $sha and .head.repo.full_name == $repo and (.head.ref | startswith("ci/tag-bump-"))' \
  "$tmp/pr.json" >/dev/null
# The local commit is the one this job just generated. Reject unexpected paths
# or edits beyond image tags and OCR readiness before submitting approval.
python3 "$(dirname "$0")/validate-promotion.py" "$EXPECTED_HEAD_SHA"
jq -n --arg sha "$EXPECTED_HEAD_SHA" \
  '{event:"APPROVE", commit_id:$sha, body:"PennyPilot promotion validation passed: successful build and manifest-only image/probe changes. Automatic merge waits for passing checks."}' > "$tmp/review.json"
curl --fail-with-body -sS -H "Authorization: Bearer $REVIEW_TOKEN" \
  -H 'Accept: application/vnd.github+json' -H 'Content-Type: application/json' \
  --request POST "$api/pulls/$PR_NUMBER/reviews" --data-binary "@$tmp/review.json" > "$tmp/result.json"
echo "Promotion approval submitted for $EXPECTED_HEAD_SHA"
